// Expected body: { engine, cycle, pred_rul, lo, hi }  (from a model service or the TrustRUL artifacts)
const b = $input.first().json.body;
const PULL_AT = 8; // best safe threshold found in MaintenanceSimEnv: 0 failures in 100 engines, about 8 cycles wasted
const ok = ['engine', 'cycle', 'pred_rul', 'lo', 'hi'].every(k => typeof b[k] === 'number');
if (!ok) return [{ json: { error: 'send numbers: engine, cycle, pred_rul, lo, hi' } }];
const action = b.pred_rul <= PULL_AT ? 'PULL' : 'CONTINUE';
const review = (b.hi - b.lo) > 40.1 ? 'HUMAN_REVIEW' : 'auto';
return [{ json: { engine: b.engine, cycle: b.cycle, action, review, rule: `pull when predicted remaining life <= ${PULL_AT} cycles`, note: 'simulation-derived rule on simulated engines, not for real maintenance decisions' } }];
